		Search = 1,
		Image = "texture\\tipbox\\tip00133",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"大贤者霸肋门德的众多研究之一的符文石碑，是将这个世界中所有生命和物质所拥有的符文之力提取出来，转化为冒险家可以利用的特定力量的石碑。\n\t\t符文的力量因各自冒险区域而异，因此具有不同的效果形态，可以将各种符文套组组合起来，根据需要更换套组效果并装备。\n\t\t\n\t\t◆ 符文套组\n\t\t◆ 符文套组是由2到6个符文碎片组成的一个单位。\n\t\t◆ 符文套组的构成要素及效果因冒险区域而异。\n\t\t◆ 符文套组必须激活才能装备。\n\t\t◆ 符文套组效果因符文碎片的构成而异。\n\t\t◆ 符文套组效果也会受到强化的影响。\n\t\t\n\t\t◆ 符文碎片\n\t\t◆ 符文碎片是通过提取道具中的符文之力而制成的合成物质。\n\t\t◆ 必须完成符文碎片，才能发挥符文套组的真正效果。\n\t\t◆ 为完成装备道具的符文碎片，需务必经过雕刻过程。\n\t\t◆ 雕刻装备道具的精炼值、随机属性、卡片及附魔信息将全部消失。\n\t\t\n\t\t◆ 符文套组的强化\n\t\t◆ 激活的符文套组可强化为特定道具。\n\t\t◆ 通过强化可使符文套组的效果更强大。\n\t\t\n\t\t◆ 分解\n\t\t◆ 卡片所拥有的符文之力可以通过分解转化为符文石碑所需的形式。\n\t\t◆ BOSS卡片会分解为更特别的形态。\n\t\t\n\t\t[符文石碑的位置]\n\t\t◆ <NAVI>[普隆德拉]<INFO>prontera,161,192,0,101,0,0</INFO></NAVI>\n\t\t◆ <NAVI>[朱诺]<INFO>yuno,142,177,0,101,0,0</INFO></NAVI>\n\t\t◆ <NAVI>[拉赫]<INFO>rachel,131,144,0,101,0,0</INFO></NAVI>\n\t\t◆ <NAVI>[冰封之城]<INFO>icecastle,71,230,0,101,0,0</INFO></NAVI>\n\t\t◆ <NAVI>[霸肋门德大宅]<INFO>ba_maison,137,111,0,101,0,0</INFO></NAVI>\n\t\t\n\t\t<TIPBOX>游玩<INFO>1002</INFO></TIPBOX>\n\t\t<TIPBOX>查看目录<INFO>1000</INFO></TIPBOX>"
